R=explorations/compile-ladder/rung-overflow-natives/record.md; L=explorations/fortress-gap-ledger.md; python3 - <<'EOF'
import re
L=open('/home/user/fortress/explorations/fortress-gap-ledger.md',encoding='utf-8').read().split('\n')
R=open('/home/user/fortress/explorations/compile-ladder/rung-overflow-natives/record.md',encoding='utf-8').read().split('\n')
def cols(line):
    # split on unescaped pipes not inside backticks
    out=[];cur='';tick=False
    for ch in line:
        if ch=='`': tick=not tick
        if ch=='|' and not tick: out.append(cur);cur=''
        else: cur+=ch
    out.append(cur)
    return len(out)
for l in L:
    if re.match(r'^\| 44[78] \|',l): print(l[:8], cols(l))
hdr=[i for i,l in enumerate(L) if l.startswith('| #') or l.startswith('| row')]
print('headers', hdr[-3:], [L[i][:120] for i in hdr[-2:]])
for l in R:
    if re.match(r'^\| 4[45][0-9] \|',l): print(l[:8], cols(l))
EOF
sed -n 290,300p $L | cut -c1-200

